import java.io.IOException;
import java.util.Scanner;
import java.util.stream.IntStream;

public class NekoAndAkiPrank {
    private final static long MOD = 1_000_000_007;

    public void solve() throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] prev = new long[n + 1];
        prev[0] = 1;
        long tWays = IntStream.range(1, 2 * n)
            .mapToObj(i -> {
                long[] cur = new long[n + 1];
                cur[0] = prev[1];
                cur[n] = prev[n - 1];
                for (int k = 1; k < n; k++) {
                    cur[k] = (prev[k - 1] + prev[k + 1]) % MOD;
                }
                prev = cur;
                return i;
            })
            .filter(i -> i % 2 == 1)
            .flatMapToLong(i -> {
                int limit = Math.min(i, 2 * n - i);
                return IntStream.rangeClosed(0, limit)
                    .mapToLong(k -> prev[k]);
            })
            .reduce(0, (a, b) -> (a + b) % MOD);
        System.out.println(tWays);
    }

    public static void main(String[] args) throws IOException {
        NekoAndAkiPrank solution = new NekoAndAkiPrank();
        solution.solve();
    }
}
